//! Parity of the Rust outbox decisions with the TypeScript functions, over
//! `ts_vectors.json` (generated by running `orderOfflineChanges` and
//! `decideOfflineBatchReceipt` on the cases, including every refusal branch).
use super::deferred_delete::deferred_delete_replay_json;
use super::outbox_order::order_offline_changes_json;
use super::outbox_receipt::offline_batch_receipt_json;
use super::routing_restrictions::model_routing_restrictions_json;
use serde_json::{Value, json};

fn vectors() -> Value {
    serde_json::from_str(include_str!("ts_vectors.json")).expect("vectors parse")
}

#[test]
fn outbox_order_equals_typescript() {
    for case in vectors()["order"].as_array().expect("order cases") {
        let out = order_offline_changes_json(&json!({"rows": case["changes"]}).to_string())
            .expect("protocol-valid input");
        let got: Value = serde_json::from_str(&out).expect("json");
        assert_eq!(got["ready"], case["ready"], "{}", case["name"]);
        assert_eq!(got["retained"], case["retained"], "{}", case["name"]);
    }
}

#[test]
fn outbox_receipt_equals_typescript() {
    for case in vectors()["receipt"].as_array().expect("receipt cases") {
        let input = json!({"changeIds": case["ids"], "terminalConflictDeleteIds": case["term"],
            "successfulIds": case["ok"], "counts": case.get("counts").cloned().unwrap_or(Value::Null)});
        let got: Value = serde_json::from_str(
            &offline_batch_receipt_json(&input.to_string()).expect("protocol-valid input"),
        ).expect("json");
        assert_eq!(got["accepted"], case["accepted"], "{}", case["name"]);
        assert_eq!(got["retiredConflictIds"], case["retired"], "{}", case["name"]);
    }
}

#[test]
fn routing_restrictions_equal_typescript() {
    let cases: Value = serde_json::from_str(include_str!("ts_routing_vectors.json")).expect("routing vectors");
    for case in cases.as_array().expect("routing cases") {
        let got: Value = serde_json::from_str(
            &model_routing_restrictions_json(&case["profile"].to_string()).expect("protocol-valid input"),
        ).expect("json");
        assert_eq!(got["ok"], case["ok"], "{}", case["name"]);
        if case["ok"] == json!(true) {
            assert_eq!(got["restrictions"], case["restrictions"], "{}", case["name"]);
        }
    }
}

#[test]
fn deferred_delete_replay_equals_typescript() {
    let cases: Value = serde_json::from_str(include_str!("ts_deferred_delete_vectors.json")).expect("vectors");
    for case in cases.as_array().expect("cases") {
        let got: Value = serde_json::from_str(
            &deferred_delete_replay_json(&case["input"].to_string()).expect("protocol-valid input"),
        ).expect("json");
        assert_eq!(got["eligible"], case["eligible"], "{}", case["name"]);
    }
}

#[test]
fn malformed_payloads_are_protocol_errors() {
    assert_eq!(order_offline_changes_json("{").unwrap_err(), "protocol");
    assert_eq!(order_offline_changes_json("{\"rows\":[{\"type\":\"draft\"}]}").unwrap_err(), "protocol");
    assert_eq!(offline_batch_receipt_json("{\"changeIds\":[1]}").unwrap_err(), "protocol");
    assert_eq!(deferred_delete_replay_json("{\"editorOnChat\":1}").unwrap_err(), "protocol");
    assert_eq!(model_routing_restrictions_json("[]").unwrap_err(), "protocol");
}
